{
  "predictors": [
    {
      "name": "Recent Dividend Initiation",
      "construction": "Indicator variable equal to 1 if a firm initiated a dividend payment in the last 12 months, 0 otherwise.",
      "rationale": "Dividend initiations signal management's confidence in future cash flows and financial stability.",
      "higher_returns_for": "stocks with a recent dividend initiation."
    },
    {
      "name": "Earnings Estimate Dispersion",
      "construction": "Standard deviation of analyst earnings forecasts for a firm, scaled by the absolute mean forecast, over the past 12 months.",
      "rationale": "Higher dispersion indicates greater uncertainty, which might lead to mispricing and subsequent correction.",
      "higher_returns_for": "low values of the measure."
    },
    {
      "name": "Industry Concentration Ratio",
      "construction": "Herfindahl-Hirschman Index of revenue shares within the firm's industry, calculated annually.",
      "rationale": "Firms in less concentrated industries may have more competitive pressures and risk, affecting returns.",
      "higher_returns_for": "stocks in less concentrated industries."
    },
    {
      "name": "CEO Tenure",
      "construction": "Number of years the current CEO has been in position, updated annually.",
      "rationale": "Shorter-tenured CEOs might pursue more aggressive growth strategies to establish their leadership.",
      "higher_returns_for": "firms with shorter CEO tenure."
    },
    {
      "name": "Relative Workforce Growth",
      "construction": "Annual percentage change in number of employees relative to the industry average.",
      "rationale": "Rapid workforce expansion could signal growth opportunities or overextension.",
      "higher_returns_for": "firms with higher relative workforce growth."
    },
    {
      "name": "Supplier Dependency Ratio",
      "construction": "Proportion of a firm's cost of goods sold attributed to its top three suppliers, reported annually.",
      "rationale": "High dependency on suppliers may indicate vulnerability to supply chain disruptions.",
      "higher_returns_for": "firms with lower supplier dependency ratios."
    },
    {
      "name": "R&D Intensity Change",
      "construction": "Annual percentage change in R&D expenses divided by total sales.",
      "rationale": "Increasing R&D intensity may reflect strategic investment in future innovation and growth.",
      "higher_returns_for": "firms with increasing R&D intensity."
    },
    {
      "name": "Foreign Revenue Exposure",
      "construction": "Percentage of total revenue derived from foreign operations, updated annually.",
      "rationale": "Firms with higher foreign exposure may benefit from global market opportunities and diversification.",
      "higher_returns_for": "firms with higher foreign revenue exposure."
    },
    {
      "name": "Patent Approval Rate",
      "construction": "Ratio of patents approved to patents filed over the last three years.",
      "rationale": "Higher approval rates may indicate a firm's ability to innovate and protect intellectual property effectively.",
      "higher_returns_for": "firms with higher patent approval rates."
    },
    {
      "name": "Insider Trading Volume",
      "construction": "Total volume of insider trades as a percentage of shares outstanding, over the past 6 months.",
      "rationale": "High insider trading activity could signal private information about future prospects.",
      "higher_returns_for": "firms with higher insider trading volumes."
    }
  ]
}
